-- Atomic starts and list snapshots, consent visibility and cross-owner constraints.
select no_plan();
select tests.create_shoppers_fixture();
select tests.act_as('signed_in_shopper');
select lives_ok($$select public.start_plan_session('90000000-0000-0000-0000-000000000001','{"occasion":"fixture"}','fixture','fresh',null,now())$$,'signed-in shopper can start session');
select is((select count(*) from public.plan_sessions where input_hash = 'fresh'),1::bigint,'session belongs to caller');
select is((select count(*) from public.plan_sessions where credits_reservation_id is not null),0::bigint,'credit settlement hook leaves reservation empty');
select throws_ok($$select public.start_plan_session('90000000-0000-0000-0000-000000000001','{}','fixture','bad-qr','95000000-0000-0000-0000-000000000002',now())$$,'23514',null,'QR from another retailer refused');
select throws_ok($$select public.start_plan_session('90000000-0000-0000-0000-000000000001','[]','fixture','bad-answers',null,now())$$,'23514',null,'answers must be an object');
select throws_ok($$select public.start_plan_session('90000000-0000-0000-0000-000000000001','{}','fixture','no-age')$$,'23514',null,'omitted age confirmation refused');
select throws_ok($$select public.start_plan_session('90000000-0000-0000-0000-000000000001','{}','fixture','future-age',null,now() + interval '1 day')$$,'23514',null,'future age confirmation refused');
select lives_ok($$select public.create_list('90000000-0000-0000-0000-000000000001','[{"product_id":"60000000-0000-0000-0000-000000000001","quantity":2}]','5555555555555555',current_date + 1,'a1000000-0000-0000-0000-000000000001')$$,'list saves own candidate and items atomically');
select is((select quantity from public.list_items where list_id = (select id from public.lists where till_code = '5555555555555555')),2::smallint,'quantity snapshotted');
select is((select unit_price_minor from public.list_items where list_id = (select id from public.lists where till_code = '5555555555555555')),2500::bigint,'price comes from current store facts');
select is((select status from public.plan_sessions where id = 'a0000000-0000-0000-0000-000000000001'),'listed','candidate session marked listed');
select ok((select picked_at is not null from public.plan_candidates where id = 'a1000000-0000-0000-0000-000000000001'),'candidate pick recorded');
select throws_ok($$select public.create_list('90000000-0000-0000-0000-000000000002','[{"product_id":"60000000-0000-0000-0000-000000000001","quantity":1}]','6666666666666666',current_date + 1,'a1000000-0000-0000-0000-000000000002')$$,'42501',null,'another shopper candidate refused');
select throws_ok($$select public.create_list('90000000-0000-0000-0000-000000000001','[{"product_id":"60000000-0000-0000-0000-000000000001","quantity":1,"unit_price_minor":1}]','6666666666666666',current_date + 1)$$,'23514',null,'caller cannot supply prices');
select throws_ok($$select public.create_list('90000000-0000-0000-0000-000000000001','[{"product_id":"60000000-0000-0000-0000-000000000001","quantity":1},{"product_id":"60000000-0000-0000-0000-000000000002","quantity":1}]','6666666666666666',current_date + 1)$$,'23514',null,'unavailable second item refuses complete list');
select is((select count(*) from public.lists where till_code = '6666666666666666'),0::bigint,'failed list leaves no parent');
select throws_ok($$select public.create_list('90000000-0000-0000-0000-000000000001','[]','6666666666666666',current_date + 1)$$,'23514',null,'empty list refused');
select throws_ok($$select public.create_list('90000000-0000-0000-0000-000000000001','[{"product_id":"60000000-0000-0000-0000-000000000001","quantity":11}]','6666666666666666',current_date + 1)$$,'23514',null,'quantity above available stock refused');
select throws_ok($$select public.create_list('90000000-0000-0000-0000-000000000001','[{"product_id":"60000000-0000-0000-0000-000000000001","quantity":0}]','6666666666666666',current_date + 1)$$,'23514',null,'zero quantity refused');
select throws_ok($$select public.create_list('90000000-0000-0000-0000-000000000001','[{"product_id":"60000000-0000-0000-0000-000000000001","quantity":1}]','6666666666666666',current_date - 1)$$,'23514',null,'expired validity refused');
reset role;
select is((select stock_qty from public.store_prices where store_id = '90000000-0000-0000-0000-000000000001'),10::int,'lists do not reserve stock');
update public.range_items set price_minor = 3000;
select is((select unit_price_minor from public.list_items where list_id = (select id from public.lists where till_code = '5555555555555555')),2500::bigint,'list price survives retailer price changes');
select tests.act_as('anonymous_shopper');
select lives_ok($$select public.start_plan_session('90000000-0000-0000-0000-000000000002','{}','fixture','anonymous',null,now())$$,'anonymous shopper can plan');
select lives_ok($$select public.create_list('90000000-0000-0000-0000-000000000002','[{"product_id":"60000000-0000-0000-0000-000000000001","quantity":1}]','7777777777777777',current_date + 1)$$,'anonymous shopper can create list');
reset role;
select tests.act_as('organisation_owner');
select is(jsonb_array_length(public.shop_customers('10000000-0000-0000-0000-000000000001')),1,'Customers includes only visible consent');
select is(public.shop_customers('10000000-0000-0000-0000-000000000001')->0->>'shopper_id',tests.get_supabase_uid('signed_in_shopper')::text,'Customers exposes consenting shopper only');
select throws_ok($$select public.shop_customers('10000000-0000-0000-0000-000000000002')$$,'42501',null,'Customers rejects another organisation');
reset role;
select tests.act_as('organisation_manager');
select is(jsonb_array_length(public.shop_customers('10000000-0000-0000-0000-000000000001')),1,'manager with customer permission can read Customers');
reset role;
select tests.act_as('other_organisation_member');
select is(jsonb_array_length(public.shop_customers('10000000-0000-0000-0000-000000000002')),1,'other retailer sees its own consenting customer');
reset role;
select tests.act_as('supplier_member');
select throws_ok($$select public.shop_customers('10000000-0000-0000-0000-000000000001')$$,'42501',null,'supplier cannot read Customers');
reset role;
update public.memberships set store_ids = array['90000000-0000-0000-0000-000000000001'::uuid] where profile_id = tests.get_supabase_uid('organisation_manager');
select tests.act_as('organisation_manager');
select throws_ok($$select public.shop_customers('10000000-0000-0000-0000-000000000001')$$,'42501',null,'store-restricted manager cannot read organisation-wide Customers');
reset role;
select tests.act_as('signed_in_shopper');
select lives_ok($$update public.follows set visible_to_shop = false$$,'shopper withdraws visibility');
reset role;
select tests.act_as('organisation_owner');
select is(jsonb_array_length(public.shop_customers('10000000-0000-0000-0000-000000000001')),0,'withdrawal immediately removes customer identity');
reset role;
set local role service_role;
select throws_ok($$insert into public.plan_edits(session_id,candidate_id,seq,source,ops,outcome) values ('a0000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000002',2,'chip','[]','applied')$$,'23503',null,'edit candidate must belong to session');
select lives_ok($$insert into public.plan_edits(session_id,candidate_id,seq,source,ops,outcome) values ('a0000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000001',2,'llm','[]','refused')$$,'llm remains a permitted historical source');
select throws_ok($$insert into public.plan_edits(session_id,candidate_id,seq,source,message,ops,outcome) values ('a0000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000001',3,'rule',repeat('x',301),'[]','refused')$$,'23514',null,'edit message limit enforced');
select throws_ok($$update public.plan_candidates set cues = '[{"t_ms":6001,"product_id":"60000000-0000-0000-0000-000000000001","position":0,"angle_deg":0}]' where id = 'a1000000-0000-0000-0000-000000000001'$$,'23514',null,'cue duration bound enforced for backend');
select throws_ok($$update public.lists set shopper_id = tests.get_supabase_uid('anonymous_shopper') where id = 'a2000000-0000-0000-0000-000000000001'$$,'23514',null,'backend cannot reassign a list');
select throws_ok($$insert into public.lists(shopper_id,store_id,plan_candidate_id,till_code,valid_until) values (tests.get_supabase_uid('anonymous_shopper'),'90000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000001','8888888888888888',current_date)$$,'23514',null,'backend cannot attach another shopper candidate');
select throws_ok($$insert into public.lists(shopper_id,store_id,till_code,valid_until) values (tests.get_supabase_uid('signed_in_shopper'),'90000000-0000-0000-0000-000000000001','1111111111111111',current_date)$$,'23505',null,'till barcode unique globally');
select throws_ok($$insert into public.lists(shopper_id,store_id,till_code,valid_until) values (tests.get_supabase_uid('signed_in_shopper'),'90000000-0000-0000-0000-000000000001','123',current_date)$$,'23514',null,'till barcode needs sixteen digits');
reset role;
update public.stores set status = 'closed' where id = '90000000-0000-0000-0000-000000000001';
select tests.act_as('signed_in_shopper');
select throws_ok($$select public.start_plan_session('90000000-0000-0000-0000-000000000001','{}','fixture','closed',null,now())$$,'23514',null,'closed store refuses session');
reset role;
update public.profiles set status = 'suspended' where id = tests.get_supabase_uid('signed_in_shopper');
select tests.act_as('signed_in_shopper');
select throws_ok($$select public.start_plan_session('90000000-0000-0000-0000-000000000002','{}','fixture','suspended',null,now())$$,'42501',null,'suspended shopper cannot start');
select throws_ok($$select public.create_list('90000000-0000-0000-0000-000000000002','[]','9999999999999999',current_date)$$,'42501',null,'suspended shopper cannot list');
reset role;
set local role service_role;
select throws_ok($$update public.plan_sessions set shopper_id = tests.get_supabase_uid('organisation_owner') where id = 'a0000000-0000-0000-0000-000000000001'$$,'23514',null,'backend cannot transfer planning history');
select throws_ok($$update public.follows set shopper_id = tests.get_supabase_uid('organisation_owner') where shopper_id = tests.get_supabase_uid('signed_in_shopper')$$,'23514',null,'backend cannot transfer consent');
select lives_ok($$update public.follows set consent_text_version = 'reconfirmed',consented_at = now() - interval '1 year' where shopper_id = tests.get_supabase_uid('signed_in_shopper')$$,'consent choices record database time');
select is((select consented_at from public.follows where shopper_id = tests.get_supabase_uid('signed_in_shopper')),now(),'client cannot backdate consent');
reset role;
update public.memberships set store_ids = '{}' where profile_id = tests.get_supabase_uid('organisation_manager');
select tests.act_as('organisation_manager');
select is((select count(*) from public.lists),0::bigint,'empty store scope hides redeemed lists');
select is((select count(*) from public.list_items),0::bigint,'empty store scope hides list items');
select finish();
